package org.firstinspires.ftc.teamcode.tuning;

import com.qualcomm.robotcore.eventloop.opmode.LinearOpMode;
import com.qualcomm.robotcore.eventloop.opmode.TeleOp;
import com.qualcomm.robotcore.hardware.PwmControl;
import com.qualcomm.robotcore.hardware.Servo;
import com.qualcomm.robotcore.util.Range;

import org.firstinspires.ftc.teamcode.config.DeviceNames;
import org.firstinspires.ftc.teamcode.config.Tuned;
import org.firstinspires.ftc.teamcode.subsystems.Ramp;

import java.util.Locale;

// Generated by refract-suite ftc-construct. PRACTICE ONLY. Setup program 4 (prerequisites E-8).
// One servo position per step: the front gate (closed / open), then the back gate, which has a servo each side
// (team 2026-10-17): servo 1 alone (servo 2 limp), then servo 2 matched to it while servo 1 holds, for closed and for
// open. Mirrored servos are never exactly 1 - p, so each is measured. A check with both moving together (a buzz =
// the two fight), the gate travel time from a slow-motion video, then the ramp (2 continuous servos on strings):
// its times out and in (it rests up by itself; the servos stop between runs). A servo only moves
// after square is pressed; the ramp only runs while square is held.
@TeleOp(name = "4 Servo Positions", group = "19859 Setup")
public class ServoPositioner extends LinearOpMode {
    private static final double BIG = 0.01, SMALL = 0.001;
    private static final double FPS = 240;

    private static final int FG = 0, BG = 1, BG2 = 2;
    private static final String[] NAMES = {DeviceNames.FRONT_GATE, DeviceNames.BACK_GATE, DeviceNames.BACK_GATE_2};

    private static final class Target {
        final int servo, partner;
        final String title, key;
        final String[] instructions;

        // partner: the other back-gate servo, -2 = limp, else held at the value of that target index
        Target(int servo, int partner, String title, String key, String... instructions) {
            this.servo = servo;
            this.partner = partner;
            this.title = title;
            this.key = key;
            this.instructions = instructions;
        }

        // read when used, not when the class loads: a value from the robot's results file arrives after that
        double configValue() {
            try {
                return Tuned.class.getField(key).getDouble(null);
            } catch (ReflectiveOperationException e) {
                return Double.NaN;
            }
        }
    }

    private static final int LIMP = -2, NONE = -1;
    private static final String MATCH = "Servo 1 holds the gate. Press square, then step servo 2 (R2 / L2) until the buzz stops. Keep"
            + " going until it starts again on the other side, then come back halfway: neither servo pushes.";
    private static final Target[] TARGETS = {
            new Target(FG, NONE, "Front gate: closed", "frontGateClosed",
                    "Move the front gate so it holds an element away from the front flywheel.",
                    "Check with an element in place: it must not touch the flywheel."),
            new Target(FG, NONE, "Front gate: open", "frontGateOpen",
                    "Move the front gate so an element passes through freely."),
            new Target(BG, LIMP, "Back gate servo 1: closed", "backGateClosed",
                    "Servo 2 is limp. Move servo 1 (bg) so the back gate holds an element away from the back flywheel.",
                    "Check with an element in place: it must not touch the flywheel."),
            new Target(BG2, 2, "Back gate servo 2: closed", "backGate2Closed", MATCH),
            new Target(BG, LIMP, "Back gate servo 1: open", "backGateOpen",
                    "Servo 2 is limp. Move servo 1 (bg) so an element passes through freely."),
            new Target(BG2, 4, "Back gate servo 2: open", "backGate2Open", MATCH),
    };
    private static final int FRONT_CLOSED = 0, FRONT_OPEN = 1, BACK_CLOSED = 2, BACK2_CLOSED = 3, BACK_OPEN = 4, BACK2_OPEN = 5;
    private static final int BOTH_CHECK = TARGETS.length, GATE_TIME = BOTH_CHECK + 1,
            RAMP_OUT = GATE_TIME + 1, RAMP_IN = RAMP_OUT + 1, STEPS = RAMP_IN + 1;

    @Override
    public void runOpMode() {
        Guide g = new Guide(telemetry, 4);
        Servo[] servos = new Servo[NAMES.length];
        StringBuilder missing = new StringBuilder();
        for (int i = 0; i < NAMES.length; i++) {
            try {
                servos[i] = hardwareMap.get(Servo.class, NAMES[i]);
            } catch (IllegalArgumentException e) {
                missing.append(NAMES[i]).append(' ');
            }
        }
        Ramp ramp = null;
        try {
            ramp = new Ramp(hardwareMap);
        } catch (IllegalArgumentException e) {
            missing.append(DeviceNames.RAMP_LEFT).append(' ').append(DeviceNames.RAMP_RIGHT).append(' ');
        }

        while (opModeInInit()) {
            g.header(0, 0, "Before you start");
            if (missing.length() > 0) g.notReady("servo names " + missing + "(program 1)");
            g.say("The ramp runs here: program 2's ramp direction step comes first.");
            g.say("You set " + TARGETS.length + " gate servo positions, check the back gate, time the gates, then the ramp.");
            g.say("Nothing moves until you press square on a step. Keep fingers out of the ramp and gates.");
            g.doThis("Ramp folded up (stowed) by hand. Press START.");
            g.update();
        }
        if (isStopRequested() || missing.length() > 0) return;

        double[] value = new double[TARGETS.length];
        boolean[] live = new boolean[TARGETS.length];
        for (int i = 0; i < TARGETS.length; i++) value[i] = Double.isNaN(TARGETS[i].configValue()) ? 0.5 : TARGETS[i].configValue();
        int step = 0, frames = 0, outFrames = 0, inFrames = 0;
        boolean gatesOpen = false, recorded = false, started = false;
        int lastStep = -1;
        String note = "";

        while (opModeIsActive()) {
            boolean next = gamepad1.crossWasPressed(), back = gamepad1.triangleWasPressed(), square = gamepad1.squareWasPressed();
            boolean bigUp = gamepad1.rightBumperWasPressed(), bigDown = gamepad1.leftBumperWasPressed();
            boolean smallUp = gamepad1.rightTriggerWasPressed(), smallDown = gamepad1.leftTriggerWasPressed();
            boolean frameUp = gamepad1.dpadUpWasPressed(), frameDown = gamepad1.dpadDownWasPressed();
            if (next || back) note = "";
            if (back && step > 0 && step < STEPS) step--;
            // a step's set-up runs once each time it is entered
            if (step != lastStep) {
                started = false;
                lastStep = step;
            }
            int frameStep = (frameUp ? 1 : 0) - (frameDown ? 1 : 0) + (bigUp ? 10 : 0) - (bigDown ? 10 : 0);

            if (step < TARGETS.length) {
                Target target = TARGETS[step];
                ramp.drive(0);
                if (square) live[step] = true;
                value[step] = Range.clip(value[step] + (bigUp ? BIG : 0) - (bigDown ? BIG : 0)
                        + (smallUp ? SMALL : 0) - (smallDown ? SMALL : 0), 0, 1);
                if (live[step]) servos[target.servo].setPosition(value[step]);
                if (target.partner == LIMP) limp(servos[BG2]);
                else if (target.partner >= 0) servos[BG].setPosition(value[target.partner]);

                g.header(step + 1, STEPS, target.title);
                g.why(target.servo == BG2 ? "The back gate has a servo each side: the second must agree with the first, or they fight and burn."
                        : "The gate holds elements off the flywheel until firing.");
                g.goal(target.servo == BG2 ? "Both servos hold the gate, neither buzzes." : target.key.contains("Closed") ? "Holds an element clear of the flywheel." : "An element passes freely.");
                for (String line : target.instructions) g.doThis(line);
                g.value("Position", String.format(Locale.US, "%.3f", value[step]) + (live[step] ? "" : "   (not moving yet: press square)"));
                g.keys("square = move the servo there, R1 / L1 = +/- 0.01, R2 / L2 = +/- 0.001, cross = save and next"
                        + (step > 0 ? ", triangle = back" : ""));
                if (next) {
                    if (!live[step]) {
                        note = "press square first and look at the real position";
                    } else {
                        note = g.record(target.key, String.format(Locale.US, "%.3f", value[step]));
                        // the next step on the same servo starts where this one ended; servo 2 starts mirrored from servo 1
                        int n = step + 1;
                        if (n < TARGETS.length && !live[n] && Double.isNaN(TARGETS[n].configValue())) {
                            if (TARGETS[n].servo == target.servo) value[n] = value[step];
                            else if (TARGETS[n].servo == BG2) value[n] = 1 - value[TARGETS[n].partner];
                            live[n] = TARGETS[n].servo == target.servo;
                        }
                        step++;
                    }
                }
            } else if (step == BOTH_CHECK) {
                if (!started) {
                    gatesOpen = false;
                    setBack(servos, value, false);
                    started = true;
                }
                if (square) {
                    gatesOpen = !gatesOpen;
                    setBack(servos, value, gatesOpen);
                }
                g.header(step + 1, STEPS, "Back gate: both servos together");
                g.why("In a match both back-gate servos move at once. If they disagree they push against each other.");
                g.goal("Closed and open: no buzz, the gate does what it should.");
                g.doThis("Press square a few times (closed <-> open). Listen and touch: no buzz, nothing hot.");
                g.doThis("Closed: an element is held clear of the flywheel. Open: it passes freely.");
                g.say("A buzz in one place: triangle back to that servo-2 step and step it down until quiet.");
                g.value("Back gate", gatesOpen ? "OPEN" : "closed");
                g.keys("square = open / close, cross = it is quiet both ways, triangle = back");
                if (next) step++;
            } else if (step == GATE_TIME) {
                if (!started) {
                    gatesOpen = false;
                    servos[FG].setPosition(value[FRONT_CLOSED]);
                    setBack(servos, value, false);
                    started = true;
                }
                if (square) {
                    gatesOpen = !gatesOpen;
                    servos[FG].setPosition(gatesOpen ? value[FRONT_OPEN] : value[FRONT_CLOSED]);
                    setBack(servos, value, gatesOpen);
                }
                frames = Math.max(0, frames + frameStep);
                g.header(step + 1, STEPS, "Gate travel time");
                g.why("Firing waits this long after opening the gates before feeding.");
                g.goal("A frame count from the slow-motion video (typically a few dozen frames).");
                g.doThis("Film both gates in 240 fps slow motion (phone slo-mo) while pressing square:");
                g.say("each press moves both gates: closed -> open, next press open -> closed.");
                g.doThis("In the video, count the frames from the slower gate starting to move until it is fully open.");
                g.doThis("Enter that count here.");
                g.value("Gates", gatesOpen ? "OPEN" : "closed");
                g.value("Frames", frames + String.format(Locale.US, "  (= %.3f s at 240 fps)", frames / FPS));
                g.keys("square = open / close, dpad up / down = +/- 1 frame, R1 / L1 = +/- 10, cross = save, triangle = back");
                if (next) {
                    if (frames == 0) {
                        note = "enter the frame count first";
                    } else {
                        note = g.record("gateTravelS", String.format(Locale.US, "%.4f", frames / FPS));
                        step++;
                    }
                }
            } else if (step == RAMP_OUT || step == RAMP_IN) {
                boolean outStep = step == RAMP_OUT;
                boolean running = gamepad1.square;
                ramp.drive(running ? (outStep ? Ramp.RAMP_POWER : -Ramp.RAMP_POWER) : 0);
                if (outStep) outFrames = Math.max(0, outFrames + frameStep);
                else inFrames = Math.max(0, inFrames + frameStep);
                int count = outStep ? outFrames : inFrames;
                g.header(step + 1, STEPS, outStep ? "Ramp: time out" : "Ramp: time in");
                g.why(outStep ? "Nothing tells the code where the ramp is: it runs the servos for this long to get it out."
                        : "And this long to fold it back up.");
                g.goal("A frame count from the slow-motion video.");
                g.doThis("Film the ramp from the side in 240 fps slow motion (phone slo-mo).");
                g.doThis(outStep ? "Ramp folded up. HOLD square: the ramp goes out. Let go the moment it is fully out (on the floor stop)."
                        : "Ramp fully out. HOLD square: the ramp folds up. Let go the moment it is fully up.");
                g.doThis("In the video, count the frames from the ramp starting to move until it stops. Enter that count.");
                g.value("Ramp", running ? (outStep ? "GOING OUT" : "GOING IN") : "stopped");
                g.value("Frames", count + String.format(Locale.US, "  (= %.3f s at 240 fps)", count / FPS));
                g.keys("hold square = run, dpad up / down = +/- 1 frame, R1 / L1 = +/- 10, cross = save, triangle = back");
                if (next) {
                    if (count == 0) {
                        note = "enter the frame count first";
                    } else {
                        note = g.record(outStep ? "rampOutS" : "rampInS", String.format(Locale.US, "%.4f", count / FPS));
                        step++;
                    }
                }
            } else {
                if (!recorded) {
                    recorded = true;
                    servos[FG].setPosition(value[FRONT_CLOSED]);
                    setBack(servos, value, false);
                    g.loadNextOnStop(this);
                }
                ramp.drive(0);
                g.header(0, 0, "Done");
                g.finished("");
                g.say("The ramp servos are stopped; the ramp rests up.");
                for (int i = 0; i < TARGETS.length; i++) g.value(TARGETS[i].key, String.format(Locale.US, "%.3f", value[i]));
                g.value("gateTravelS", String.format(Locale.US, "%.3f", frames / FPS));
                g.value("rampOutS / rampInS", String.format(Locale.US, "%.3f / %.3f", outFrames / FPS, inFrames / FPS));
            }
            if (!note.isEmpty()) g.warn(note);
            g.update();
        }
        ramp.stop();
    }

    // both back-gate servos at their own closed or open position
    private static void setBack(Servo[] servos, double[] value, boolean open) {
        servos[BG].setPosition(value[open ? BACK_OPEN : BACK_CLOSED]);
        servos[BG2].setPosition(value[open ? BACK2_OPEN : BACK2_CLOSED]);
    }

    // no signal: the servo goes limp, so the other one alone sets the gate
    private static void limp(Servo servo) {
        if (servo instanceof PwmControl) ((PwmControl) servo).setPwmDisable();
    }
}
